            p.addLine(to: CGPoint(x: 7, y: 22))
            p.addCurve(to: CGPoint(x: 5, y: 20), control1: CGPoint(x: 5.8954305, y: 22), control2: CGPoint(x: 5, y: 21.104569))
            p.addLine(to: CGPoint(x: 5, y: 6))
            p.move(to: CGPoint(x: 3, y: 6))
            p.addLine(to: CGPoint(x: 21, y: 6))
            p.move(to: CGPoint(x: 8, y: 6))
            p.addLine(to: CGPoint(x: 8, y: 4))
            p.addCurve(to: CGPoint(x: 10, y: 2), control1: CGPoint(x: 8, y: 2.8954305), control2: CGPoint(x: 8.8954305, y: 2))
            p.addLine(to: CGPoint(x: 14, y: 2))
